function saveCheckoutDraft(){try{localStorage.setItem(orderDraftKey(),JSON.stringify({cart,cartKey,requestKey}));}catch{throw Error('Penyimpanan draft tidak tersedia. Pesanan belum dikirim. Aktifkan penyimpanan browser.');}}
function orderDraftKey(){return 'nexo-order-draft-v1:'+user.id;}
function persistDraft(){try{localStorage.setItem(orderDraftKey(),JSON.stringify({cart,cartKey,requestKey}));}catch{}}
function restoreDraft(){
 try{
  const d=JSON.parse(localStorage.getItem(orderDraftKey())||'null');if(!d)return;
  if(Array.isArray(d.cart)&&d.cart.length<=5&&d.cart.every(x=>typeof x?.service_id==='string'&&Number.isInteger(x.quantity)&&x.quantity>=1&&x.quantity<=99)&&new Set(d.cart.map(x=>x.service_id)).size===d.cart.length)cart=d.cart;
  if(cart.length&&typeof d.cartKey==='string'&&/^[a-zA-Z0-9_-]{16,80}$/.test(d.cartKey))cartKey=d.cartKey;
  if(typeof d.requestKey?.signature==='string'&&typeof d.requestKey?.id==='string'&&/^[a-zA-Z0-9_-]{16,80}$/.test(d.requestKey.id))requestKey=d.requestKey;
 }catch{}
}
