 for(const item of cart){const s=catalog.find(x=>x.id===item.service_id),a=node('article','');a.append(node('strong',s?.name||item.service_id),node('p',s?.price||'Tidak tersedia'));if(rentalLabel(s))a.append(node('p',rentalLabel(s)));const p=s?.policy?.promo,n=s?.base_unit_amount,at=Math.floor(Date.now()/1000),pct=p&&(p.legacy||p.start<=at&&at<p.end&&item.quantity>=p.min_quantity)?p.percent:0,unit=Number.isSafeInteger(n)?Math.max(1,Math.floor(n*(100-pct)/100)):s?.unit_amount;if(unit!=null)total+=unit*item.quantity;else unknown++;const label=node('label','Jumlah');const input=document.createElement('input');input.type='number';input.min=1;input.max=99;input.value=item.quantity;input.disabled=Boolean(cartKey);input.onchange=()=>{if(cartKey||checkoutBusy){input.value=item.quantity;return;}const n=Number(input.value);item.quantity=Number.isInteger(n)?Math.max(1,Math.min(99,n)):1;cartKey=null;persistDraft();shopView().catch(e=>status(e.message,true));};label.append(input);a.append(label);button(a,'Hapus',()=>{assertNoPendingCart();cart=cart.filter(x=>x!==item);persistDraft();return shopView();}).disabled=Boolean(cartKey);section.append(a);}
 if(!cart.length)section.append(node('p','Keranjang masih kosong.','empty'));
