async function performanceView(){const host=$('performanceBody');const d=await viewData(host,()=>api('performance'),()=>performanceView());if(!d.items.length)host.append(node('p','Belum ada pekerjaan tercatat.'));for(const [idx,x] of d.items.entries()){const a=node('article','');a.append(node('strong',(d.scope==='team'?(idx+1)+'. ':'')+x.display_name),node('p',x.completed+' selesai · '+x.active+' aktif · '+x.overdue+' terlambat'),node('p',x.reviews?'Penilaian '+x.rating+'/5 dari '+x.reviews+' ulasan':'Belum ada ulasan'));host.append(a);}button(host,'Muat ulang kinerja',()=>performanceView());}
const view=createNavigator({get:$,buttons:()=>document.querySelectorAll('[data-view]'),allowed:()=>!sessionInvalid&&Boolean(user),loaders:{performance:performanceView,shop:shopView,calendar:calendarView,business:businessView,notifications:()=>notifications(true),account:accountView,workspace:workspaceView,support:supportView,report:reportView,finance,audit,team}});
const loginMessages={invalid_client:'Konfigurasi aplikasi Discord tidak cocok. Hubungi pemilik (OAUTH-CLIENT).',invalid_grant:'Kode login tidak valid. Mulai login kembali.',invalid_state:'Sesi login kedaluwarsa. Masuk kembali.',access_denied:'Login dibatalkan.',invalid_request:'Permintaan OAuth tidak valid.',unauthorized_client:'Aplikasi belum mengizinkan login.',rate_limited:'Discord membatasi permintaan. Coba lagi nanti.',identity_error:'Identitas Discord tidak berhasil diverifikasi.',token_transport:'Koneksi pertukaran token Discord gagal.',identity_transport:'Koneksi verifikasi identitas gagal.',membership_unavailable:'Peran Discord belum dapat diverifikasi. Coba masuk kembali; jika berulang, hubungi pemilik.',worker_role_review:'Peran penjoki berubah tetapi masih ada pekerjaan aktif. Hubungi pemilik untuk rekonsiliasi.',provider_error:'Layanan login Discord sementara gagal.'};
async function init(){try{const h=await api('health');if(h.maintenance)toast('Sistem dalam pemeliharaan: perubahan transaksi dinonaktifkan.');if(!h.login_configured){status('Portal belum dikonfigurasi. Gunakan tiket Discord.');return;}try{({user}=await api('me'));}catch(e){if(e.status!==401)throw e;$('login').hidden=false;const code=new URLSearchParams(location.search).get('login_error');status(code?loginMessages[code]||'Login gagal. Coba lagi.':'Masuk untuk mengakses dashboard.');if(code)history.replaceState(null,'',location.pathname);return;}
 restoreDraft();await refreshCatalog();$('heading').textContent='Dashboard '+(roles[user.role]||'Pelanggan');$('intro').textContent=descriptions[user.role]||descriptions.customer;$('identity').textContent=user.display_name;$('roleBadge').textContent=roles[user.role]||'Pelanggan';$('account').hidden=false;document.body.classList.add('dashboard-mode');$('account').prepend($('status'));$('logout').hidden=false;$('themeToggle').hidden=false;document.body.dataset.role=user.role;let light=false;try{light=localStorage.getItem('nexo-theme')==='light';}catch{}setTheme(light);$('orderTitle').textContent=oversees()?'Semua pesanan':user.role==='worker'?'Antrean & pekerjaan':'Pesanan saya';for(const b of document.querySelectorAll('[data-view]'))b.hidden=['finance','workspace'].includes(b.dataset.view)?!(['owner','worker'].includes(user.role)||user.finance_access):b.dataset.view==='report'?!oversees():b.dataset.view==='performance'?!oversees()&&user.role!=='worker':['audit','team','business'].includes(b.dataset.view)?user.role!=='owner':false;await load();syncConnection();status('Terhubung.');if(h.maintenance)toast('Sistem dalam pemeliharaan: perubahan transaksi dinonaktifkan.');notifications().catch(()=>{});setInterval(()=>{if(!document.hidden&&!sessionInvalid)notifications(!$('notificationsView').hidden).catch(()=>{});},30000);}catch(e){status('Portal tidak tersedia: '+e.message);}}
$('request').onsubmit=async e=>{
 e.preventDefault();const b=e.submitter;if(checkoutBusy||cartKey){status(pendingMessage,true);return;}
 b.disabled=true;checkoutBusy=true;let sent=false,retry=Boolean(requestKey);
 try{
  let payload={service_id:$('service').value,quantity:Number($('quantity').value)};
  const signature=JSON.stringify(payload);
  if(requestKey&&requestKey.signature!==signature){
   const previous=JSON.parse(requestKey.signature);
   if(!confirm('Pesanan sebelumnya belum pasti: '+(catalog.find(s=>s.id===previous.service_id)?.name||previous.service_id)+' × '+previous.quantity+'. Ulangi pesanan sebelumnya dengan ID yang sama?'))throw Error(pendingMessage);
   payload=previous;
  }
  requestKey??={signature:JSON.stringify(payload),id:crypto.randomUUID()};
  saveCheckoutDraft();sent=true;const {order}=validateCheckoutReceipt(await api('orders',{...payload,request_id:requestKey.id}),[payload],{single:true});
  requestKey=null;persistDraft();await load();status('Permintaan tercatat: '+order.id);
 }catch(e){if(shouldClearPendingCheckout({sent,retry,error:e})){requestKey=null;persistDraft();}status(e.message+(requestKey?' '+pendingMessage:''),true);}
 finally{checkoutBusy=false;b.disabled=false;}
};
$('team').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('team/role',{user_id:$('member').value,role:$('role').value});await team();status('Peran diperbarui.');}catch(e){status(e.message,true);}finally{b.disabled=false;}};
function setTheme(light){document.body.classList.toggle('light-theme',light);$('themeToggle').textContent=light?'Tema gelap':'Tema terang';$('themeToggle').setAttribute('aria-pressed',String(light));try{localStorage.setItem('nexo-theme',light?'light':'dark');}catch{}}
$('themeToggle').onclick=()=>setTheme(!document.body.classList.contains('light-theme'));
const safe=fn=>()=>Promise.resolve().then(fn).catch(e=>status(e.message,true));
$('filter').onchange=safe(()=>load());$('orderSearch').onchange=safe(()=>load());$('orderSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();safe(()=>load())();}};$('refresh').onclick=safe(()=>load());$('moreOrders').onclick=safe(()=>load(true));$('loadTeam').onclick=safe(()=>team());$('moreTeam').onclick=safe(()=>team(true));$('moreFinance').onclick=safe(()=>finance(true));$('moreAudit').onclick=safe(()=>audit(true));$('closeDetail').onclick=()=>{$('orderDialog').close();detailId=null;detailSerial++;};$('logout').onclick=safe(async()=>{await api('auth/logout',{});location.reload();});for(const b of document.querySelectorAll('[data-view]'))b.onclick=safe(()=>view(b.dataset.view));init();

function globalSearch(){
 const input=$('globalSearch'),raw=input.value.trim(),q=searchKey(raw),host=$('globalResults');host.replaceChildren();host.hidden=!q;input.setAttribute('aria-expanded',String(Boolean(q)));if(!q||sessionInvalid||!user)return;
 const close=()=>{host.hidden=true;input.setAttribute('aria-expanded','false');};let n=0;
 for(const menu of document.querySelectorAll('.dashboard-nav button:not([hidden])'))if(searchKey(menu.textContent).includes(q)){button(host,'Menu: '+menu.textContent,async()=>{close();await view(menu.dataset.view);});n++;}
 for(const item of searchCatalog(catalog,raw)){button(host,'Layanan: '+item.name,async()=>{await view('orders');$('service').value=item.id;$('service').focus();close();});n++;}
 if(!n)host.append(node('p','Tidak ada menu atau layanan yang cocok. Coba cari pesanan.','empty'));
 button(host,'Cari pada pesanan yang dapat diakses',async()=>{close();await view('orders');$('filter').value='';$('orderSearch').value=raw;await load();});
}
$('globalSearch').addEventListener('input',globalSearch);
$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Escape'){$('globalResults').hidden=true;e.currentTarget.setAttribute('aria-expanded','false');}else if(e.key==='Enter'){e.preventDefault();$('globalResults').querySelector('button')?.focus();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&user&&!sessionInvalid&&!$('orderDialog').open){e.preventDefault();$('globalSearch').focus();globalSearch();}});
